<?php
/** Private operator DB adapter. No HTTP routes, submission helpers or research-answer generation. */
function cv_lock(string $scope,callable $fn): mixed {
    $name='cloud-qa:'.cv_scope($scope);cv_need((int)one('SELECT GET_LOCK(?,5) AS acquired',[$name])['acquired']===1,'Synthetic scope is busy.');
    // Match the application's existing trusted operator-CLI pattern, scoped to this mutation.
    cv_need(PHP_SAPI==='cli','Synthetic mutations are CLI only.');$hadAdmin=array_key_exists('admin',$_SESSION??[]);$previous=$_SESSION['admin']??null;$_SESSION['admin']=1;
    try{return tx($fn);}finally{if($hadAdmin)$_SESSION['admin']=$previous;else unset($_SESSION['admin']);query('SELECT RELEASE_LOCK(?)',[$name]);}
}
function cv_owned(array $m): array {
    $spec=cv_spec($m['scope']);$r=one('SELECT * FROM research WHERE id=?',[$m['research']['id']]);cv_need($r!==null&&$r['title']===$spec['title']&&$r['question']===$spec['question']&&$r['context']===$spec['context']&&$r['slug']===($m['research']['slug']??''),'Not the exact owned synthetic study; no action taken.');
    foreach($spec['tasks'] as $role=>$task){$t=one('SELECT * FROM workflow_tasks WHERE id=? AND research_id=?',[$m['tasks'][$role]['id'],$r['id']]);cv_need($t!==null&&$t['task_key']===$task['key']&&$t['objective']===$task['objective']&&$t['deliverable']===$task['deliverable']&&$t['acceptance']===str_replace(chr(92).'n',chr(10),$task['acceptance'])&&(bool)$t['computational']===$task['computational']&&$t['kind']==='research','Synthetic task ownership mismatch.');}return $r;
}
function cv_create(array $o): array {
    return cv_lock($o['scope'],function()use($o){$spec=cv_spec($o['scope']);$existing=all('SELECT id,slug FROM research WHERE title=?',[$spec['title']]);cv_need(count($existing)<=1,'Duplicate scope detected; do not guess ownership.');
        if($existing){$r=$existing[0];$tasks=[];foreach($spec['tasks'] as $role=>$task){$rows=all('SELECT id,revision FROM workflow_tasks WHERE research_id=? AND task_key=?',[$r['id'],$task['key']]);cv_need(count($rows)===1,'Incomplete synthetic scope; do not repair automatically.');$tasks[$role]=['id'=>$rows[0]['id'],'revision'=>(int)$rows[0]['revision']];}}
        else{$category=one('SELECT id FROM categories WHERE enabled=1 ORDER BY id LIMIT 1');cv_need($category!==null,'An enabled category is required.');$created=create_research($spec+['category_id'=>(int)$category['id'],'terms'=>1,'display_name'=>'Synthetic acceptance fixture','calculation_help'=>'maybe','external_tools'=>'none']);$rid=$created['id'];moderate('request',$rid,'Approved','Explicit isolated synthetic Cloud acceptance fixture; no research answer or scientific result.');query("UPDATE workflow_tasks SET state='Superseded' WHERE research_id=?",[$rid]);$tasks=[];
            foreach($spec['tasks'] as $role=>$task){$id=wf_new_task($rid,1,$task['key'],'research',$task['title'],$task['objective'],$task['deliverable'],str_replace(chr(92).'n',chr(10),$task['acceptance']),[],$task['computational']);$tasks[$role]=['id'=>$id,'revision'=>1];}
            wf_set_state($rid,'Open for Research','Synthetic research-stage fixture, not an AI-authored accepted plan.');touch_context($rid);$r=research($rid,false);}
        $m=['version'=>1,'scope'=>$o['scope'],'destination'=>$o['destination'],'candidate'=>$o['candidate'],'tree'=>$o['tree'],'source_identity'=>'Operator-reported; independently verify the deployed candidate before live acceptance.','research'=>['id'=>$r['id'],'slug'=>$r['slug']],'tasks'=>$tasks,'notice'=>'Setup created no research answer, submission packet, accepted result or source-inspection claim.'];cv_owned($m);return $m;});
}
function cv_inspect(array $m): array {
    return ['scope'=>$m['scope'],'research_id'=>$m['research']['id'],'tasks'=>all('SELECT id,task_key,state,revision,accepted_id,computational FROM workflow_tasks WHERE research_id=? ORDER BY task_key',[$m['research']['id']]),'result_count'=>(int)one('SELECT COUNT(*) AS n FROM workflow_submissions WHERE research_id=?',[$m['research']['id']])['n']];
}
function cv_cleanup(array $m,array $o): array {
    cv_need(!empty($o['apply'])&&($o['confirm-scope']??'')===$m['scope'],'Cleanup requires --apply and exact --confirm-scope.');
    return cv_lock($m['scope'],function()use($m){if(!one('SELECT id FROM research WHERE id=?',[$m['research']['id']])){cv_need(!one('SELECT id FROM workflow_tasks WHERE id IN (?,?,?)',array_column($m['tasks'],'id')),'Manifest has surviving foreign tasks.');return ['scope'=>$m['scope'],'already_absent'=>true];}cv_owned($m);cv_need(!one('SELECT id FROM volunteer_assignments WHERE research_id=? AND ended_at IS NULL LIMIT 1',[$m['research']['id']]),'Stop/release active assignments before scoped cleanup.');cv_need(!one('SELECT id FROM task_reservations WHERE research_id=? AND ended_at IS NULL AND expires_at>UTC_TIMESTAMP() LIMIT 1',[$m['research']['id']]),'Release active task reservations before scoped cleanup.');purge_request($m['research']['id'],$m['research']['id']);return ['scope'=>$m['scope'],'removed_research_id'=>$m['research']['id'],'notice'=>'Only the explicitly manifested owned synthetic study was purged.'];});
}
function cv_snapshot(array $m,string $phase,array $o): array {
    cv_need(in_array($phase,['before_check','after_check','after_submit','after_recovery','after_stop'],true),'Unknown observation phase.');
    cv_need($o['candidate']===$m['candidate']&&$o['tree']===$m['tree'],'Observation source differs from the fixture manifest.');
    cv_need(!db()->inTransaction(),'Read-only observation needs its own transaction.');query('SET TRANSACTION READ ONLY');
    return tx(function()use($m,$phase){$r=cv_owned($m);$tid=$m['tasks']['narrative']['id'];$task=one('SELECT * FROM workflow_tasks WHERE id=? AND research_id=?',[$tid,$r['id']]);$visible=false;try{research($r['id']);$visible=$task['visibility']==='public';}catch(HttpError $error){if($error->status!==404)throw $error;}$results=[];$stopped=false;
        foreach(all('SELECT * FROM workflow_submissions WHERE research_id=? AND task_id=? ORDER BY created_at,id',[$r['id'],$tid]) as $row){$meta=json_decode($row['metadata'],true,64,JSON_THROW_ON_ERROR);$bindings=all('SELECT a.* FROM volunteer_assignments a JOIN browser_returns b ON b.id=a.return_id WHERE a.research_id=? AND a.task_id=? AND b.result_id=?',[$r['id'],$tid,$row['id']]);$binding=false;
            if(count($bindings)===1){$a=$bindings[0];$b=one('SELECT * FROM browser_returns WHERE id=?',[$a['return_id']]);$s=one('SELECT * FROM volunteer_sessions WHERE id=?',[$a['session_id']]);$scope=json_decode($b['scope'],true,32,JSON_THROW_ON_ERROR);$binding=$s&&($s['session_profile']??'general')==='restricted_web_v1'&&$s['actor_hash']===$b['actor_hash']&&$b['actor_hash']===$row['actor_hash']&&(int)$a['task_revision']===$m['tasks']['narrative']['revision']&&(int)($scope['revision']??0)===(int)$a['task_revision']&&($scope['volunteer_assignment_id']??'')===$a['id']&&($scope['volunteer_session_id']??'')===$s['id']&&($scope['submission_key']??'')===$row['nonce']&&($scope['context_id']??'')===$row['snapshot_id']&&$b['research_id']===$r['id']&&$b['task_id']===$tid;$stopped=!empty($s['stopped_at']);}
            $resultVisible=false;try{rs_read($r['id'],$row['id']);$resultVisible=true;}catch(HttpError $error){if($error->status!==404)throw $error;}
            $e=$meta['evidence']??[];$executed=(bool)array_filter($e['calculations']??[],fn($c)=>($c['status']??'')==='executed')||!empty($e['tool_builds'])||!empty($e['reproductions'])||!empty($e['calculation_reviews'])||!empty($e['tool_reviews']);
            $results[]=['id'=>$row['id'],'admission'=>$row['admission'],'outcome'=>$row['outcome'],'submission_method'=>$row['submission_method'],'task_signature_valid'=>($meta['verification']['task_signature']??'')==='valid','restricted_binding'=>(bool)$binding,'visible'=>$resultVisible,'model_derived_count'=>cv_model_derived_count($e),'executed_or_tool_evidence'=>$executed];}
        $controlIds=[$m['tasks']['execution']['id'],$m['tasks']['reproduction']['id']];
        return ['version'=>1,'scope'=>$m['scope'],'destination'=>$m['destination'],'candidate'=>$m['candidate'],'tree'=>$m['tree'],'phase'=>$phase,'observed_at'=>(new DateTimeImmutable('now',new DateTimeZone('UTC')))->format('Y-m-d\TH:i:s.u\Z'),'research_id'=>$r['id'],'task_id'=>$tid,'revision'=>(int)$task['revision'],'accepted_id'=>$task['accepted_id'],'visible'=>$visible,'study_result_count'=>(int)one('SELECT COUNT(*) AS n FROM workflow_submissions WHERE research_id=?',[$r['id']])['n'],'control_assignments'=>(int)one('SELECT COUNT(*) AS n FROM volunteer_assignments WHERE research_id=? AND task_id IN (?,?)',[$r['id'],...$controlIds])['n'],'control_results'=>(int)one('SELECT COUNT(*) AS n FROM workflow_submissions WHERE research_id=? AND task_id IN (?,?)',[$r['id'],...$controlIds])['n'],'session_stopped'=>$stopped,'results'=>$results];});
}
